artifact.schema:
export interface PatternExtension<TOptions = unknown, TConfig = unknown> {
  readonly id:    string;
  readonly apply: (
    def: PatternDefinition<TConfig>,
    options: TOptions,
  ) => PatternDefinition<TConfig>;
}

export function defineExtension<TOptions, TConfig = unknown>(
  spec: { id: string; apply: PatternExtension<TOptions, TConfig>['apply'] }
): (options: TOptions) => PatternExtension<TOptions, TConfig>;

built-in-extensions.ext:
withErrorBoundary({ fallbackId: 'product-table-error' })
// Wraps Component in an error boundary that renders a fallback pattern on crash.
// Isolates failures so one pattern crash does not blank the whole view.

artifact.custom-extension-example:
// packages/extensions/with-analytics/src/index.ts
import { defineExtension } from '@surte/core';

export const withAnalytics = defineExtension<{ stream: string }>({
  id: 'extension.analytics',
  apply: (def, options) => ({
    ...def,
    extensions: [...def.extensions],  // preserve chain
    selector: (ctx, config) => {
      const props = def.selector(ctx, config);
      return {
        ...props,
        onMount:   () => ctx['analytics:write'].track(`${options.stream}.mounted`),
        onUnmount: () => ctx['analytics:write'].track(`${options.stream}.unmounted`),
      };
    },
  }),
});

// usage:
const ProductTablePattern = definePattern({
  // ...
  extensions: [
    withTelemetry({ events: ['rowSelected'] }),
    withAnalytics({ stream: 'products.table' }),
    withErrorBoundary({ fallbackId: 'product-table-error' }),
  ],
});
